{
  "vulnerable_symbols": [
    "ThreadContext.put",
    "Logger.info"
  ],
  "trigger": "攻击者可控字符串被写入 Log4j ThreadContext，并在配置了 Context Lookup 的日志 Pattern 中被记录/解析，导致自引用 lookup 无限递归 DoS。",
  "preconditions": [
    "log4j-core 版本在 2.0-alpha1 至 2.16.0（不含 2.12.3/2.3.1）",
    "日志 PatternLayout 配置了 Context Lookup（如 ${ctx:...}）"
  ],
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "Python script that generates a self-referential Log4j2 lookup payload and sends it via HTTP GET/POST requests to trigger CVE-2021-45105 uncontrolled recursion, causing denial of service."
    },
    {
      "src": 2,
      "kind": "in_the_wild",
      "quote": "VulnCheck reports CVE-2021-45105 use in known ransomware campaigns."
    }
  ],
  "fixed_version": "2.17.0",
  "summary_zh": "Log4j2日志含上下文查找时，可控线程上下文串会无限递归致拒绝服务，升级2.17.0。"
}
